/* @catalog — generated by `npm run catalog:generate`; do not edit by hand.
 * Internal
 *   Types: Entry
 *   Functions: credits, byline, longName, seededRandom
 *   Constants: organizationRoles, ellipsis
 * Tests
 *   - phrase-free bylines equal the frozen pre-change literals
 *   - credits are ordered by order with ties kept in input order
 *   - a join phrase is used only between two adjacent shown Credits
 *   - a byline over 500 units ends after the last whole name that fits
 *   - a first name over the cap is cut at a grapheme boundary
 *   - plain-name bylines drop empty names, keep repeated names, and share the cap
 *   - random Credit lists always yield capped bylines both native clients accept
 * @end-catalog */

/**
 * Pins the shared server byline composer. Phrase-free cases repeat the literals frozen by the S0
 * baseline (test/listener/nativeBylineValidators.test.ts), so the shared helper is a pure
 * refactor for existing data; join phrases, adjacency and the 500-unit cap are new behavior.
 * A seeded property test replays random Credit lists through both ported native validators.
 * Invisible and combining characters are written as escapes so editors cannot alter them.
 */
import assert from 'node:assert/strict';
import test from 'node:test';

import {
    type CatalogCreditRole,
    type CatalogCreditSubjectType,
    catalogCreditRoles,
    normalizeStoredCatalogCredits
} from '../../src/models/catalogCredit';
import {
    type BylineCredit,
    type BylineSegment,
    bylineTruncationMarker,
    capCatalogByline,
    catalogBylineSegments,
    catalogDisplayByline,
    composeCatalogByline,
    composePlainNameByline,
    maximumBylineLength,
    toBylineCredit,
    undocumentedAttributionByline
} from '../../src/services/catalog/catalogByline';
import { nativeBylineLimit, nativeDisplayTextVerdict } from '../support/nativeDisplayTextValidators';

const organizationRoles = new Set<CatalogCreditRole>(['label', 'publisher', 'distributor', 'presenter']);
const ellipsis = bylineTruncationMarker;

type Entry = [name: string, role: CatalogCreditRole, joinPhrase?: string];

/** Builds validated-order byline Credits; Organization roles imply an Organization subject. */
const credits = (...entries: Entry[]): BylineCredit[] => entries.map(([name, role, joinPhrase], order) => ({
    subjectType: organizationRoles.has(role) ? 'organization' : 'artist',
    role,
    order,
    name,
    ...(joinPhrase === undefined ? {} : { joinPhrase })
}));
const byline = (...entries: Entry[]) => composeCatalogByline(credits(...entries));
/** A synthetic name at the 200-character limit both clients enforce for Credit names. */
const longName = (label: string) => `${label} ${'x'.repeat(199 - label.length)}`;

test('phrase-free bylines equal the frozen pre-change literals', () => {
    assert.equal(byline(
        ['Northwind Choir', 'primary'], ['Ipsum Trio', 'primary'], ['Sitamet Brass', 'featured'],
        ['Dolor Quartet', 'primary'], ['Consectetur Strings', 'performer'], ['Adipiscing Studio', 'composer'],
        ['Lorem Records', 'label']
    ), 'Northwind Choir, Ipsum Trio, Sitamet Brass, Dolor Quartet, Consectetur Strings');
    assert.equal(byline(['Lorem Records', 'label'], ['Elit Publishing', 'publisher'], ['Tempor Distribution', 'distributor']),
        'Lorem Records, Elit Publishing, Tempor Distribution');
    assert.equal(byline(['Adipiscing Studio', 'composer'], ['Ipsum Trio', 'producer'], ['Lorem Records', 'label']),
        'Lorem Records');
    assert.equal(byline(['Adipiscing Studio', 'composer'], ['Ipsum Trio', 'producer'], ['Dolor Quartet', 'remixer']),
        'Adipiscing Studio, Ipsum Trio, Dolor Quartet');
    assert.equal(byline(
        ['Northwind Choir', 'primary'], ['Northwind Choir', 'performer'], ['Northwind Choir', 'primary'], ['Ipsum Trio', 'primary']
    ), 'Northwind Choir, Ipsum Trio');
    // Callers trim names; the helper uses them verbatim and never applies NFC.
    assert.equal(byline(['Padded Ensemble', 'primary'], ['Ipsum Trio', 'featured']), 'Padded Ensemble, Ipsum Trio');
    assert.equal(catalogDisplayByline('unknown', []), undocumentedAttributionByline);
    assert.equal(undocumentedAttributionByline, 'Attribution not documented');
    assert.equal(byline(['Ensemble Ce\u0301leste \u{1F3BB}', 'primary'], ['Gamma \u{1F44D}\u{1F3FD} Duo \u{1F1EF}\u{1F1F5}', 'primary']),
        'Ensemble Ce\u0301leste \u{1F3BB}, Gamma \u{1F44D}\u{1F3FD} Duo \u{1F1EF}\u{1F1F5}');
    const voices = Array.from({ length: 50 }, (_, index): Entry => [`Voice ${String(index + 1).padStart(2, '0')}`, 'primary']);
    const fifty = byline(...voices);
    assert.equal(fifty, voices.map(([name]) => name).join(', '));
    assert.equal(fifty.length, 498);
    // Hidden or unnamed subjects show nothing; a documented owner with none visible keeps ''.
    assert.equal(byline(['', 'primary'], ['', 'label']), '');
    assert.equal(catalogDisplayByline('documented', credits(['A', 'primary'])), 'A');
});

test('credits are ordered by order with ties kept in input order', () => {
    const shuffled: BylineCredit[] = [
        { subjectType: 'artist', role: 'primary', order: 2, name: 'C' },
        { subjectType: 'artist', role: 'primary', order: 0, name: 'A', joinPhrase: ' & ' },
        { subjectType: 'artist', role: 'primary', order: 1, name: 'B1' },
        { subjectType: 'artist', role: 'primary', order: 1, name: 'B2' }
    ];
    assert.equal(composeCatalogByline(shuffled), 'A & B1, B2, C');
});

test('a join phrase is used only between two adjacent shown Credits', () => {
    assert.equal(byline(['A', 'primary', ' & '], ['B', 'primary', ' feat. '], ['C', 'featured']), 'A & B feat. C');
    // A hidden middle Credit, an omitted repeated name and an out-of-tier Credit each break adjacency.
    assert.equal(byline(['A', 'primary', ' & '], ['', 'primary', ' & '], ['B', 'primary']), 'A, B');
    assert.equal(byline(['A', 'primary', ' & '], ['A', 'performer', ' feat. '], ['B', 'primary']), 'A, B');
    assert.equal(byline(['A', 'performer', ' & '], ['C', 'composer', ' / '], ['B', 'performer']), 'A, B');
    // A label after primary Credits stays out of the byline, and no phrase trails the last name.
    assert.equal(byline(['A', 'primary', ' & '], ['B', 'primary', ' / '], ['Label', 'label']), 'A & B');
    assert.equal(byline(['A', 'primary', ' & '], ['B', 'primary', ' feat. ']), 'A & B');
    assert.equal(byline(['Label', 'label', ' / '], ['Publisher', 'publisher']), 'Label / Publisher');
    assert.equal(byline(['A', 'primary', '\u3001'], ['B', 'primary', '&'], ['C', 'primary']), 'A\u3001B&C');
    assert.deepEqual(catalogBylineSegments(credits(['A', 'primary', ' & '], ['B', 'primary'])), [
        { separator: '', name: 'A' },
        { separator: ' & ', name: 'B' }
    ]);
});

test('a byline over 500 units ends after the last whole name that fits', () => {
    assert.equal(maximumBylineLength, 500);
    assert.equal(ellipsis, '\u2026');
    const exact = byline(['a'.repeat(249), 'primary'], ['b'.repeat(249), 'primary']);
    assert.equal(exact, `${'a'.repeat(249)}, ${'b'.repeat(249)}`);
    assert.equal(exact.length, 500);
    assert.equal(byline(['a'.repeat(249), 'primary'], ['b'.repeat(250), 'primary']), `${'a'.repeat(249)}${ellipsis}`);

    const [alpha, beta, gamma] = ['Long Alpha', 'Long Beta', 'Long Gamma'].map(longName);
    const three = byline([alpha, 'primary'], [beta, 'primary'], [gamma, 'primary']);
    assert.equal(three, `${alpha}, ${beta}${ellipsis}`);
    assert.equal(three.length, 403);
    for (const unit of ['\u6F22', '\u{1F3BB}', 'e\u0301']) {
        const names = ['A', 'B', 'C'].map((label) => label + unit.repeat(Math.floor(199 / unit.length)));
        const result = byline(...names.map((name): Entry => [name, 'primary']));
        assert.equal(result, `${names[0]}, ${names[1]}${ellipsis}`, JSON.stringify(unit));
        assert.ok(result.length <= 500);
    }
    // Phrase separators count toward the cap.
    assert.equal(byline(['a'.repeat(242), 'primary', ' & '], ['b'.repeat(255), 'primary']).length, 500);
    assert.equal(byline(['a'.repeat(242), 'primary', ' & '], ['b'.repeat(256), 'primary']), `${'a'.repeat(242)}${ellipsis}`);
    assert.equal(byline(['a'.repeat(242), 'primary'], ['b'.repeat(256), 'primary']).length, 500);
});

test('a first name over the cap is cut at a grapheme boundary', () => {
    assert.equal(byline(['a'.repeat(600), 'primary'], ['B', 'primary']), `${'a'.repeat(499)}${ellipsis}`);
    const emoji = byline(['\u{1F3BB}'.repeat(300), 'primary']);
    assert.equal(emoji, `${'\u{1F3BB}'.repeat(249)}${ellipsis}`);
    assert.equal(/[\uD800-\uDBFF](?![\uDC00-\uDFFF])/.test(emoji), false);
    assert.equal(byline(['e\u0301'.repeat(300), 'primary']), `${'e\u0301'.repeat(249)}${ellipsis}`);
    // Trailing whitespace before the cut is trimmed so the marker never follows a space.
    assert.equal(byline([`${'a'.repeat(498)} ${'b'.repeat(100)}`, 'primary']), `${'a'.repeat(498)}${ellipsis}`);
    // One grapheme longer than the cap falls back to a code-point cut.
    const oneGrapheme = `a${'\u0301'.repeat(599)}`;
    assert.equal(byline([oneGrapheme, 'primary']), `a${'\u0301'.repeat(498)}${ellipsis}`);
    assert.equal(capCatalogByline([]), '');
});

test('plain-name bylines drop empty names, keep repeated names, and share the cap', () => {
    // Pre-Credit presentation: two Artists with the same name both stay listed.
    assert.equal(composePlainNameByline(['A', '', 'B', 'A', 'C']), 'A, B, A, C');
    assert.equal(composePlainNameByline([]), '');
    assert.equal(composePlainNameByline(['', '']), '');
    // The Credit-reads rollback and unmigrated Library creators use this composer.
    const [alpha, beta, gamma] = ['Long Alpha', 'Long Beta', 'Long Gamma'].map(longName);
    const creator = composePlainNameByline([alpha, beta, gamma]);
    assert.equal(creator, `${alpha}, ${beta}${ellipsis}`);
    assert.deepEqual(nativeDisplayTextVerdict(creator, nativeBylineLimit), { ios: true, android: true });
});

/** Mulberry32: a small deterministic PRNG so every run replays the same cases. */
const seededRandom = (seed: number) => () => {
    seed = (seed + 0x6D2B79F5) | 0;
    let value = Math.imul(seed ^ (seed >>> 15), 1 | seed);
    value = (value + Math.imul(value ^ (value >>> 7), 61 | value)) ^ value;
    return ((value ^ (value >>> 14)) >>> 0) / 4_294_967_296;
};

test('random Credit lists always yield capped bylines both native clients accept', () => {
    const random = seededRandom(0x5eed);
    const pick = <T>(values: readonly T[]) => values[Math.floor(random() * values.length)];
    // Pieces both ports accept inside Credit names: no Cc, Cf or ZWJ.
    const pieces = [
        'Lorem', 'ipsum', 'Dolor', 'X', '\u6F22\u5B57', '\u97F3\u697D', '\uD55C\uAE00', '\u{1F3BB}', '\u{1F3B8}',
        '\u{1F1EF}\u{1F1F5}', '\u{1F44D}\u{1F3FD}', 'e\u0301', 'n\u0303o', ' '
    ];
    const name = (long: boolean) => {
        const target = long ? 150 + Math.floor(random() * 51) : 1 + Math.floor(random() * 30);
        let value = '';
        while (Array.from(value).length < target) value += pick(pieces);
        const codePoints = Array.from(value.trim()).slice(0, 200);
        return codePoints.join('').trim() || 'Fallback';
    };
    const validPhrases = ['&', ' & ', '\u3001', ' feat. ', ' / ', ' x ', '\u00A0&\u00A0', ' and '];
    const invalidPhrases: unknown[] = ['', ' ', 'x\u200By', 'a\nb', 'x'.repeat(17), null, 5];
    const artistRoles = catalogCreditRoles.filter((role) => !organizationRoles.has(role));
    const organizationRoleList = catalogCreditRoles.filter((role) => role === 'legacyUnspecified' || organizationRoles.has(role));

    const coverage = { truncated: 0, phrased: 0 };
    for (let run = 0; run < 500; run += 1) {
        const count = 1 + Math.floor(random() * 10);
        const names: string[] = [];
        const raw = Array.from({ length: count }, (_, index) => {
            const subjectType: CatalogCreditSubjectType = random() < 0.25 ? 'organization' : 'artist';
            const phraseRoll = random();
            const joinPhrase = phraseRoll < 0.4 ? undefined : phraseRoll < 0.85 ? pick(validPhrases) : pick(invalidPhrases);
            const repeated = names.length > 0 && random() < 0.15;
            names.push(random() < 0.15 ? '' : repeated ? pick(names.filter(Boolean).concat('Fallback')) : name(random() < 0.6));
            return {
                creditId: `credit_${String(index).padStart(3, '0')}`,
                subjectType,
                subjectId: (0x64b0_0000 + index).toString(16).padStart(24, '0'),
                role: pick(subjectType === 'artist' ? artistRoles : organizationRoleList),
                order: index,
                ...(joinPhrase === undefined ? {} : { joinPhrase })
            };
        });
        const bylineCredits = normalizeStoredCatalogCredits(raw).map((credit, index) => toBylineCredit(credit, names[index]));
        const result = composeCatalogByline(bylineCredits);
        const segments = catalogBylineSegments(bylineCredits);
        const joined = segments.map((segment) => segment.separator + segment.name).join('');
        const label = `run ${run}: ${JSON.stringify(raw)} ${JSON.stringify(names)}`;

        assert.ok(result.length <= 500, label);
        if (result) assert.deepEqual(nativeDisplayTextVerdict(result, nativeBylineLimit), { ios: true, android: true }, label);
        if (segments.some((segment, index) => index > 0 && segment.separator !== ', ')) coverage.phrased += 1;
        if (joined.length <= 500) {
            assert.equal(result, joined, label);
            continue;
        }
        coverage.truncated += 1;
        assert.ok(result.endsWith(ellipsis), label);
        const body = result.slice(0, -ellipsis.length);
        const prefixes = segments.reduce<string[]>((all, segment: BylineSegment) =>
            [...all, (all[all.length - 1] ?? '') + segment.separator + segment.name], []);
        const fitting = prefixes.findIndex((prefix) => prefix === body);
        if (fitting >= 0) {
            assert.ok(prefixes[fitting + 1].length + ellipsis.length > 500, label);
        } else {
            assert.ok(segments[0].name.startsWith(body) && segments[0].name.length + ellipsis.length > 500, label);
        }
    }
    // The generator must keep exercising both the cap and join phrases.
    assert.ok(coverage.truncated >= 30, JSON.stringify(coverage));
    assert.ok(coverage.phrased >= 50, JSON.stringify(coverage));
});
